<?php require_once __DIR__.'/../includes/functions.php';require_login();$u=current_user();$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT o.*,p.name product_name,oi.quantity,oi.printing FROM orders o JOIN order_items oi ON oi.order_id=o.id JOIN products p ON p.id=oi.product_id WHERE o.id=? AND o.customer_id=? LIMIT 1");$s->execute([$id,$u['id']]);$o=$s->fetch();if(!$o)die('Order tidak ditemukan.');$pmt=db()->prepare("SELECT * FROM payments WHERE order_id=? ORDER BY created_at DESC");$pmt->execute([$id]);$payments=$pmt->fetchAll();$st=db()->prepare("SELECT * FROM order_status_history WHERE order_id=? ORDER BY created_at");$st->execute([$id]);$history=$st->fetchAll();$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_FILES['payment'])){$up=save_upload($_FILES['payment'],'payments');if($up['ok']){db()->prepare("INSERT INTO payments(order_id,amount,method,proof_path,status) VALUES(?,?, 'bank_transfer',?,'pending')")->execute([$id,$o['total_amount'],$up['path']]);$msg='Bukti pembayaran berhasil diunggah.';}else $msg=$up['error'];}
?><!doctype html><html lang="id"><head><?php include __DIR__.'/../includes/head.php';?></head><body><?php include __DIR__.'/../includes/header.php';?><main class="content"><a href="dashboard.php">← Kembali</a><div class="page-head"><div><p class="eyebrow"><?=e($o['order_number'])?></p><h1><?=e($o['product_name'])?></h1></div><span class="badge"><?=e(str_replace('_',' ',$o['status']))?></span></div><div class="grid two"><section class="panel"><h3>Ringkasan</h3><p>Jumlah: <?=e($o['quantity'])?></p><p>Printing: <?=e($o['printing'])?></p><p>Total: <strong>Rp <?=number_format($o['total_amount'],0,',','.')?></strong></p></section><section class="panel"><h3>Upload bukti pembayaran</h3><?php if($msg):?><div class="alert"><?=e($msg)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="file" name="payment" accept=".jpg,.jpeg,.png,.pdf" required><button class="btn">Upload</button></form></section></div><section class="panel"><h3>Tracking</h3><div class="timeline"><?php foreach($history as $h):?><div><b><?=e(str_replace('_',' ',$h['status']))?></b><small><?=e($h['created_at'])?></small></div><?php endforeach;?></div></section></main></body></html>